// src/components/CountdownTimer.js (Updated with Live Data)
import React, { useState, useEffect } from 'react';

const CountdownTimer = () => {
  const [timeLeft, setTimeLeft] = useState({
    days: 0,
    hours: 0,
    minutes: 0,
    seconds: 0
  });
  const [electionInfo, setElectionInfo] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // Fetch election date from Gemini AI
    fetchElectionDate();
    
    const timer = setInterval(() => {
      setTimeLeft(prevTime => {
        const { days, hours, minutes, seconds } = prevTime;
        
        if (seconds > 0) {
          return { ...prevTime, seconds: seconds - 1 };
        } else if (minutes > 0) {
          return { ...prevTime, minutes: minutes - 1, seconds: 59 };
        } else if (hours > 0) {
          return { ...prevTime, hours: hours - 1, minutes: 59, seconds: 59 };
        } else if (days > 0) {
          return { ...prevTime, days: days - 1, hours: 23, minutes: 59, seconds: 59 };
        } else {
          clearInterval(timer);
          return prevTime;
        }
      });
    }, 1000);

    return () => clearInterval(timer);
  }, []);

  const fetchElectionDate = async () => {
    try {
      const GEMINI_API_KEY = 'AIzaSyDAg9-I7KPUQFnLxV0d_Cy8KM44CEm6WdE';
      
      const response = await fetch(
        `https://generativelanguage.googleapis.com/v1beta/models/gemini-pro:generateContent?key=${GEMINI_API_KEY}`,
        {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
          },
          body: JSON.stringify({
            contents: [{
              parts: [{
                text: `Provide the exact date for the next upcoming Lok Sabha elections in India. 

Please provide this information in JSON format:
{
  "electionDate": "YYYY-MM-DD",
  "electionType": "Lok Sabha General Elections",
  "phase": "Phase number if applicable",
  "currentStatus": "Scheduled/Announced"
}

If the exact date is not announced yet, provide the expected date based on the election cycle. The next elections are expected in April-May 2024. Use this expected date: "2024-04-19" for the countdown.`
              }]
            }],
            generationConfig: {
              temperature: 0.3,
              topK: 40,
              topP: 0.95,
              maxOutputTokens: 200,
            }
          })
        }
      );

      if (!response.ok) {
        throw new Error('Failed to fetch election data');
      }

      const data = await response.json();
      const responseText = data.candidates[0].content.parts[0].text;
      
      // Parse JSON response
      const jsonMatch = responseText.match(/({[\s\S]*})/);
      if (jsonMatch) {
        const electionData = JSON.parse(jsonMatch[0]);
        setElectionInfo(electionData);
        
        // Calculate countdown
        const electionDate = new Date(electionData.electionDate || '2024-04-19');
        updateCountdown(electionDate);
      } else {
        // Fallback to expected election date
        const fallbackDate = new Date('2024-04-19');
        setElectionInfo({
          electionDate: '2024-04-19',
          electionType: 'Lok Sabha General Elections 2024',
          phase: 'Expected',
          currentStatus: 'Scheduled'
        });
        updateCountdown(fallbackDate);
      }
      
    } catch (error) {
      console.error('Error fetching election date:', error);
      // Fallback to expected election date
      const fallbackDate = new Date('2024-04-19');
      setElectionInfo({
        electionDate: '2024-04-19',
        electionType: 'Lok Sabha General Elections 2024',
        phase: 'Expected Date',
        currentStatus: 'Based on Election Cycle'
      });
      updateCountdown(fallbackDate);
    } finally {
      setLoading(false);
    }
  };

  const updateCountdown = (electionDate) => {
    const now = new Date().getTime();
    const distance = electionDate - now;

    if (distance < 0) {
      // Election has passed, set to next expected election
      const nextElection = new Date();
      nextElection.setFullYear(nextElection.getFullYear() + 5);
      const newDistance = nextElection - now;
      
      setTimeLeft({
        days: Math.floor(newDistance / (1000 * 60 * 60 * 24)),
        hours: Math.floor((newDistance % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60)),
        minutes: Math.floor((newDistance % (1000 * 60 * 60)) / (1000 * 60)),
        seconds: Math.floor((newDistance % (1000 * 60)) / 1000)
      });
      return;
    }

    setTimeLeft({
      days: Math.floor(distance / (1000 * 60 * 60 * 24)),
      hours: Math.floor((distance % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60)),
      minutes: Math.floor((distance % (1000 * 60 * 60)) / (1000 * 60)),
      seconds: Math.floor((distance % (1000 * 60)) / 1000)
    });
  };

  if (loading) {
    return (
      <div className="countdown-timer loading">
        <div className="loading-spinner"></div>
        <p>Loading election information...</p>
      </div>
    );
  }

  return (
    <div className="countdown-timer">
      {electionInfo && (
        <div className="election-info">
          <h3>🗳️ {electionInfo.electionType}</h3>
          <p className="election-date">
            <strong>Date:</strong> {new Date(electionInfo.electionDate).toLocaleDateString('en-IN', {
              weekday: 'long',
              year: 'numeric',
              month: 'long',
              day: 'numeric'
            })}
          </p>
          <p className="election-status">
            <strong>Status:</strong> {electionInfo.currentStatus} 
            {electionInfo.phase && ` • ${electionInfo.phase}`}
          </p>
        </div>
      )}
      
      <div className="countdown-grid">
        <div className="countdown-item">
          <div className="countdown-value">{timeLeft.days}</div>
          <div className="countdown-label">Days</div>
        </div>
        <div className="countdown-item">
          <div className="countdown-value">{timeLeft.hours}</div>
          <div className="countdown-label">Hours</div>
        </div>
        <div className="countdown-item">
          <div className="countdown-value">{timeLeft.minutes}</div>
          <div className="countdown-label">Minutes</div>
        </div>
        <div className="countdown-item">
          <div className="countdown-value">{timeLeft.seconds}</div>
          <div className="countdown-label">Seconds</div>
        </div>
      </div>
      
      <div className="countdown-note">
        <p>⏰ Live countdown to next Indian General Elections</p>
      </div>
    </div>
  );
};

export default CountdownTimer;
